#include <stddef.h>

void
clear_memory (void *mem1, size_t nclears1, void *mem2, size_t nclears2)
{
  size_t *d1 = (size_t *) mem1;

  *(d1 + 0) = 0;
  *(d1 + 1) = 0;
  *(d1 + 2) = 0;
  if (nclears1 > 3)
    {
      *(d1 + nclears1 - 4) = 0;
      *(d1 + nclears1 - 4 + 1) = 0;
      *(d1 + nclears1 - 4 + 2) = 0;
      *(d1 + nclears1 - 4 + 3) = 0;
    }

  double *d2 = (double *) mem2;

  *(d2 + 0) = 0;
  *(d2 + 1) = 0;
  *(d2 + 2) = 0;
  if (nclears2 > 3)
    {
      *(d2 + nclears2 - 4) = 0;
      *(d2 + nclears2 - 4 + 1) = 0;
      *(d2 + nclears2 - 4 + 2) = 0;
      *(d2 + nclears2 - 4 + 3) = 0;
    }
}

/* { dg-do compile } */
/* { dg-options "-O2 -march=x86-64-v3" } */
/* { dg-final { scan-assembler-times "xor\[a-z\]*\[\t \]*%xmm\[0-9\]\+,\[^,\]*" 1 } } */

#include <stddef.h>

float
clear_memory (void *mem, size_t clearsize)
{
  size_t *d = (size_t *) mem;
  size_t nclears = clearsize / sizeof (size_t);

  *(d + 0) = 0;
  *(d + 1) = 0;
  *(d + 2) = 0;
  if (nclears > 9)
    {
      *(d + 5) = 0;
      *(d + 5 + 1) = 0;
      *(d + 5 + 2) = 0;
      *(d + 5 + 3) = 0;
      *(d + nclears - 8) = 0;
      *(d + nclears - 8 + 1) = 0;
      *(d + nclears - 8 + 2) = 0;
      *(d + nclears - 8 + 3) = 0;
    }
  else
    {
      *(d + 1) = 0;
      *(d + 2) = 0;
      *(d + 3) = 0;
      *(d + 4) = 0;
      *(d + nclears - 4) = 0;
      *(d + nclears - 4 + 1) = 0;
      *(d + nclears - 4 + 2) = 0;
      *(d + nclears - 4 + 3) = 0;
    }

  return nclears;
}
